from pathlib import Path
import shutil,csv,json,hashlib
src=Path('outputs/iusaf');dst=Path('outputs/iusaf-stewardship');dst.mkdir(exist_ok=True)
original={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in src.iterdir() if p.is_file()}
for p in src.iterdir():
 if p.is_file() and p.name!='IUSAF-staircase.html':shutil.copy2(p,dst/p.name)
rows=list(csv.DictReader(open('/Users/pauloldham/Documents/cali-allocation-model-unscale-v3/country_allocations.csv')))
data={}
for r in rows:
 b=float(r['share_iusaf']);sid=r['is_sids'].lower()=='true';land=(float(r['share_strict'])-.955*b-(.03/39 if sid else 0))/.015
 assert land>-1e-10
 data[r['iso3c']]={'sids':sid,'landShare':max(0,land),'referenceStrict':float(r['share_strict']),'referenceGini':float(r['share_gini_minimum'])}
assert len(data)==142 and sum(r['sids'] for r in data.values())==39
assert abs(sum(r['landShare'] for r in data.values())-1)<1e-9
(dst/'stewardship-data.js').write_text('const StewardshipData = '+json.dumps(data)+';\n')
s=(dst/'index.html').read_text().replace('<title>','<title>Stewardship edition · ').replace('IUSAF / EQUITY EXPLORER','IUSAF / STEWARDSHIP EXPLORER').replace('Choose a fund size. Six bands.','Choose a fund size. Compare equity and stewardship.').replace('Band 1 : Band 6 · per Party','Pure equity · Band 1 : Band 6').replace('Adjacent allocations','Pure equity · adjacent steps').replace('<h2>Allocation per Party</h2>','<h2>Pure equity reference per Party</h2>').replace('<h2>Allocation detail</h2>','<h2>Pure equity reference detail</h2>').replace('Find a country’s allocation','Find a country’s pure equity reference').replace('Pure IUSAF equity allocation<br><span>SOSAC and TSAC are not included.','Pure equity reference above<br><span>Combined allocations appear below.').replace('Equity component only / 100% of the illustrative fund','Stewardship edition / components share one fund')
controls='''<section class="details stewardship"><h2>Recognising ocean and terrestrial stewardship</h2><label for="scenario">Allocation scenario</label><select id="scenario"><option value="pure">Pure IUSAF reference · no stewardship</option><option value="ocean">SOSAC only · 3% SOSAC / 0% TSAC</option><option value="strict" selected>Strict preset · 3% SOSAC / 1.5% TSAC</option><option value="gini">Gini minimum preset · 3% SOSAC / 2.5% TSAC</option><option value="boundary">Band boundary preset · 3% SOSAC / 3% TSAC</option></select><button id="stewardship-reset">Reset weights and stewardship defaults</button><p id="pool-summary" aria-live="polite"></p><p>SOSAC: Small Island Developing States Ocean Stewardship Allocation Component (recognises greater ocean stewardship responsibilities and structural constraints of UN recognised SIDS).</p><p>TSAC: Terrestrial Stewardship Allocation Component (recognises greater stewardship responsibilities associated with size, not species richness).</p><p class="hint">The components divide the selected fund; they are not added on top. SOSAC is shared equally among 39 SIDS. TSAC follows each Party’s share of eligible land area.</p><p id="preset-note"></p></section>'''
s=s.replace('<section class="workspace">',controls+'<section class="workspace">')
combined='''<section class="details stewardship"><h2>Combined allocations</h2><p>Band averages are shown below. Countries in the same band can receive different totals.</p><div id="combined-chart" role="img" aria-label="Mean combined allocations by band"></div><p class="component-legend"><span>■ IUSAF equity</span><span>■ SOSAC</span><span>■ TSAC</span></p><p id="mean-order" aria-live="polite"></p><p id="country-order"></p><div class="table-wrap"><table><thead><tr><th>Band</th><th>Parties</th><th>Mean per Party</th><th>Country range</th><th>Band total</th></tr></thead><tbody id="combined-bands"></tbody></table></div><h2>Country allocations with stewardship</h2><label for="combined-search">Country name or three-letter code</label><input id="combined-search" type="search" placeholder="For example, Kenya or KEN"><p id="combined-count"></p><div class="country-results table-wrap"><table><thead><tr><th>Country</th><th>Band</th><th>IUSAF</th><th>SOSAC</th><th>TSAC</th><th>Combined</th><th>Change from pure equity</th></tr></thead><tbody id="combined-countries"></tbody></table></div><p id="combined-total"></p></section>'''
s=s.replace('<section class="details"><div class="chart-heading">',combined+'<section class="details"><div class="chart-heading">',1)
s=s.replace('<script src="app.js"></script>','<script src="stewardship-data.js"></script><script src="stewardship-model.js"></script><script src="stewardship-ui.js"></script><script src="app.js"></script>')
(dst/'index.html').write_text(s)
s=(dst/'app.js').read_text().replace(' renderCountries();',' renderCountries();renderStewardship();')
s+='\n$("scenario").addEventListener("change",()=>renderStewardship());\n$("combined-search").addEventListener("input",()=>renderStewardship());\n$("stewardship-reset").addEventListener("click",()=>{$("scenario").value="strict";$("reset").click();});\n'
(dst/'app.js').write_text(s)
(dst/'style.css').write_text((dst/'style.css').read_text()+'''\n.stewardship select{font:inherit;padding:12px;border:1px solid #aac2cc;border-radius:8px;max-width:100%;margin:12px 14px 12px 0}.stewardship label{display:block}.stewardship p{line-height:1.6}.component-legend{display:flex;gap:24px;flex-wrap:wrap}.component-legend span:nth-child(1){color:#147D92}.component-legend span:nth-child(2){color:#8761a8}.component-legend span:nth-child(3){color:#a77923}#combined-chart svg{width:100%;height:auto}.check-warning{color:#b3354b}#pool-summary{font-size:20px;font-weight:600}#combined-search{font:inherit;padding:10px;width:min(100%,400px)}\n''')
Path('work/original-iusaf-hashes.json').write_text(json.dumps(original))
